                const floorsBefore = !guardThisPart ? null : (() => {
                    const v = weeklyVolume(program, weeksOf(program));
                    const o = {};
                    Object.keys(v).forEach(pp => { const LL = landmarkFor(pp); if (LL && LL.mev)
                        o[pp] = (v[pp] || 0) >= LL.mev; });
                    return o;
                })();
