            const keep = { name: shellProgram.name, folder: shellProgram.folder, description: shellProgram.description, cycleId: shellProgram.cycleId, cycleIndex: shellProgram.cycleIndex, blockLabel: shellProgram.blockLabel, updatedAt: shellProgram.updatedAt, generationRoute: shellProgram.generationRoute };
            const out = { ...shellProgram, ...treatment, ...keep, id: shellProgram.id, createdAt: shellProgram.createdAt, seed: shellProgram.seed, engineSourceVersion: shellProgram.engineSourceVersion || liveNextProgram.engineVersion || "0.61.3" };
