            const restored = nextProgramToShellProgram(control, p.config, EXERCISES, () => p.id);
            const keep = { name: p.name, folder: p.folder, description: p.description, cycleId: p.cycleId, cycleIndex: p.cycleIndex, blockLabel: p.blockLabel, updatedAt: Date.now(), generationRoute: p.generationRoute };
            const withdrawn = { ...trial, status: "withdrawn", completedAt: Date.now(), reason: "User restored the Engine 0.61 control before logging trial workouts." };
            const next = { ...p, ...restored, ...keep, id: p.id, createdAt: p.createdAt, seed: p.seed, engineSourceVersion: p.engineSourceVersion || control.engineVersion || "0.61.3" };
